node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readLines, LineReader } from './src/lines.mjs';
const encoded = new TextEncoder().encode('a🙂\r\n\nb\rc\r');
assert.deepEqual(await readLines(Array.from(encoded, byte => Uint8Array.of(byte))), ['a🙂', '', 'b\rc\r']);
assert.deepEqual(await readLines([new TextEncoder().encode('x\n')]), ['x']);
assert.deepEqual(await readLines([new TextEncoder().encode('\n\n')]), ['', '']);
